makeMtLab(document.getElementById("lab-l16"),{id:"l16",scenarios:[{"label": "Ví dụ: 45 sang hệ 2 bằng chia liên tiếp", "note": "Theo dõi số dư; đọc từ dưới lên.", "steps": [{"t": "Đổi 45 sang hệ 2: chia liên tiếp cho 2", "html": "<p class=\"mt-calc\">Ghi lại số dư mỗi lần chia; dừng khi thương bằng 0<\/p>", "say": "<p>Số dư của phép chia cho 2 chính là chữ số hàng thấp nhất.<\/p>"}, {"t": "45 ÷ 2 = 22 dư 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>45<\/td><td>22<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table>"}, {"t": "22 ÷ 2 = 11 dư 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>45<\/td><td>22<\/td><td>1<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table>"}, {"t": "11 ÷ 2 = 5 dư 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>45<\/td><td>22<\/td><td>1<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td>0<\/td><\/tr><tr><td>11<\/td><td>5<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Đang chia 11 cho 2. Thương và số dư?", "o": ["5 dư 1", "5 dư 0", "6 dư 1"], "a": 0}}, {"t": "5 ÷ 2 = 2 dư 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>45<\/td><td>22<\/td><td>1<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td>0<\/td><\/tr><tr><td>11<\/td><td>5<\/td><td>1<\/td><\/tr><tr><td>5<\/td><td>2<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table>"}, {"t": "2 ÷ 2 = 1 dư 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>45<\/td><td>22<\/td><td>1<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td>0<\/td><\/tr><tr><td>11<\/td><td>5<\/td><td>1<\/td><\/tr><tr><td>5<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>2<\/td><td>1<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table>"}, {"t": "1 ÷ 2 = 0 dư 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>45<\/td><td>22<\/td><td>1<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td>0<\/td><\/tr><tr><td>11<\/td><td>5<\/td><td>1<\/td><\/tr><tr><td>5<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>2<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>1<\/td><td>0<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table>"}, {"t": "Đọc số dư từ dưới lên: 101101", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>45<\/td><td>22<\/td><td class=\"hi\">1<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td class=\"hi\">0<\/td><\/tr><tr><td>11<\/td><td>5<\/td><td class=\"hi\">1<\/td><\/tr><tr><td>5<\/td><td>2<\/td><td class=\"hi\">1<\/td><\/tr><tr><td>2<\/td><td>1<\/td><td class=\"hi\">0<\/td><\/tr><tr><td>1<\/td><td>0<\/td><td class=\"hi\">1<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">45 = <b>101101<\/b><sub>2<\/sub><\/p>", "say": "<p>Số dư đầu tiên là bit thấp nhất (bên phải). Kiểm tra: 32 + 8 + 4 + 1 = 45 ✓.<\/p>"}]}, {"label": "Ví dụ: 101101₂ sang hệ 10 bằng trọng số", "note": "Cộng trọng số của các bit bằng 1.", "steps": [{"t": "101101₂: mỗi bit có trọng số 2ᵏ", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Vị trí k<\/th><th scope=\"col\">5<\/th><th scope=\"col\">4<\/th><th scope=\"col\">3<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><th scope=\"col\">0<\/th><\/tr><\/thead><tbody><tr><td>Trọng số 2ᵏ<\/td><td>32<\/td><td>16<\/td><td>8<\/td><td>4<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>Bit<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>1<\/td><\/tr><\/tbody><\/table>", "say": "<p>Giống hệ 10 (Bài 1), chỉ khác cơ số: hàng k có trọng số 2ᵏ.<\/p>"}, {"t": "Cộng trọng số của các bit 1", "html": "<p class=\"mt-calc\">32 + 8 + 4 + 1 = <b>45<\/b><\/p>", "ask": {"q": "11001000₂ bằng bao nhiêu trong hệ 10?", "o": ["200", "136", "72"], "a": 0}, "say": "<p>11001000₂ = 128 + 64 + 8 = 200.<\/p>"}]}, {"label": "Ví dụ: Hệ 2 ↔ hệ 16 bằng nhóm 4 bit", "note": "Mỗi chữ số hex là 4 bit.", "steps": [{"t": "Mỗi chữ số hệ 16 ứng đúng 4 bit", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Hex<\/th><th scope=\"col\">0<\/th><th scope=\"col\">1<\/th><th scope=\"col\">…<\/th><th scope=\"col\">9<\/th><th scope=\"col\">A<\/th><th scope=\"col\">B<\/th><th scope=\"col\">C<\/th><th scope=\"col\">D<\/th><th scope=\"col\">E<\/th><th scope=\"col\">F<\/th><\/tr><\/thead><tbody><tr><td>Nhị phân<\/td><td>0000<\/td><td>0001<\/td><td>…<\/td><td>1001<\/td><td>1010<\/td><td>1011<\/td><td>1100<\/td><td>1101<\/td><td>1110<\/td><td>1111<\/td><\/tr><tr><td>Thập phân<\/td><td>0<\/td><td>1<\/td><td>…<\/td><td>9<\/td><td>10<\/td><td>11<\/td><td>12<\/td><td>13<\/td><td>14<\/td><td>15<\/td><\/tr><\/tbody><\/table>", "say": "<p>Hệ 16 dùng 0–9 và A–F. Vì 16 = 2⁴, đổi giữa hệ 2 và hệ 16 chỉ cần nhóm 4 bit.<\/p>"}, {"t": "10100101₂ → nhóm 1010 | 0101 → A5", "html": "<p class=\"mt-calc\">1010 = A · 0101 = 5 → <b>0xA5<\/b><\/p>", "ask": {"q": "Nhóm 1111 0000 viết trong hệ 16 là gì?", "o": ["F0", "0F", "150"], "a": 0}}, {"t": "0x3C → 0011 1100", "html": "<p class=\"mt-calc\">3 = 0011 · C = 1100 → <b>00111100₂<\/b> = 60<\/p>", "say": "<p>Tiền tố 0x (hoặc hậu tố h như 3Ch trong hợp ngữ) cho biết số viết ở hệ 16. Một byte luôn đúng 2 chữ số hex: vì vậy địa chỉ, mã màu, mã máy thường viết bằng hex.<\/p>"}]}, {"label": "Ví dụ: 2026 sang hệ 16", "note": "Chia liên tiếp cho 16; số dư 10–15 là A–F.", "steps": [{"t": "Đổi 2026 sang hệ 16: chia liên tiếp cho 16", "html": "<p class=\"mt-calc\">Ghi lại số dư mỗi lần chia; dừng khi thương bằng 0<\/p>", "say": "<p>Cùng cách chia liên tiếp, chỉ đổi số chia thành 16. Số dư từ 10 tới 15 viết thành A–F.<\/p>"}, {"t": "2026 ÷ 16 = 126 dư A", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>2026<\/td><td>126<\/td><td class=\"new\">A (= 10)<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "2026 ÷ 16 = 126 dư 10. Số dư 10 viết thành chữ số hex nào?", "o": ["10", "A", "G"], "a": 1}}, {"t": "126 ÷ 16 = 7 dư E", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>2026<\/td><td>126<\/td><td>A (= 10)<\/td><\/tr><tr><td>126<\/td><td>7<\/td><td class=\"new\">E (= 14)<\/td><\/tr><\/tbody><\/table>"}, {"t": "7 ÷ 16 = 0 dư 7", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>2026<\/td><td>126<\/td><td>A (= 10)<\/td><\/tr><tr><td>126<\/td><td>7<\/td><td>E (= 14)<\/td><\/tr><tr><td>7<\/td><td>0<\/td><td class=\"new\">7<\/td><\/tr><\/tbody><\/table>"}, {"t": "Đọc số dư từ dưới lên: 7EA", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>2026<\/td><td>126<\/td><td class=\"hi\">A (= 10)<\/td><\/tr><tr><td>126<\/td><td>7<\/td><td class=\"hi\">E (= 14)<\/td><\/tr><tr><td>7<\/td><td>0<\/td><td class=\"hi\">7<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">2026 = <b>7EA<\/b><sub>16<\/sub><\/p>", "say": "<p>Kiểm tra: 7 × 256 + 14 × 16 + 10 = 1 792 + 224 + 10 = 2 026 ✓.<\/p>"}]}, {"label": "Bẫy: Đọc số dư từ trên xuống", "note": "44 bị đọc thành 13.", "steps": [{"t": "Đổi 44 sang hệ 2: chia liên tiếp cho 2", "html": "<p class=\"mt-calc\">Ghi lại số dư mỗi lần chia; dừng khi thương bằng 0<\/p>", "say": "<p>Số dư của phép chia cho 2 chính là chữ số hàng thấp nhất.<\/p>"}, {"t": "44 ÷ 2 = 22 dư 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>44<\/td><td>22<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table>"}, {"t": "22 ÷ 2 = 11 dư 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>44<\/td><td>22<\/td><td>0<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table>"}, {"t": "11 ÷ 2 = 5 dư 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>44<\/td><td>22<\/td><td>0<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td>0<\/td><\/tr><tr><td>11<\/td><td>5<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table>"}, {"t": "5 ÷ 2 = 2 dư 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>44<\/td><td>22<\/td><td>0<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td>0<\/td><\/tr><tr><td>11<\/td><td>5<\/td><td>1<\/td><\/tr><tr><td>5<\/td><td>2<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table>"}, {"t": "2 ÷ 2 = 1 dư 0", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>44<\/td><td>22<\/td><td>0<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td>0<\/td><\/tr><tr><td>11<\/td><td>5<\/td><td>1<\/td><\/tr><tr><td>5<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>2<\/td><td>1<\/td><td class=\"new\">0<\/td><\/tr><\/tbody><\/table>"}, {"t": "1 ÷ 2 = 0 dư 1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Số<\/th><th scope=\"col\">Thương<\/th><th scope=\"col\">Số dư<\/th><\/tr><\/thead><tbody><tr><td>44<\/td><td>22<\/td><td>0<\/td><\/tr><tr><td>22<\/td><td>11<\/td><td>0<\/td><\/tr><tr><td>11<\/td><td>5<\/td><td>1<\/td><\/tr><tr><td>5<\/td><td>2<\/td><td>1<\/td><\/tr><tr><td>2<\/td><td>1<\/td><td>0<\/td><\/tr><tr><td>1<\/td><td>0<\/td><td class=\"new\">1<\/td><\/tr><\/tbody><\/table>"}, {"t": "Đọc từ trên xuống (sai): 001101 = 13", "html": "<p class=\"mt-calc\">Số dư theo thứ tự ghi: 0, 0, 1, 1, 0, 1 → nếu viết theo thứ tự này: 001101₂ = <b>13<\/b> ✗<\/p>", "ask": {"q": "Số dư đầu tiên (khi chia 44 cho 2) là bit nào của kết quả?", "o": ["Bit cao nhất (bên trái)", "Bit thấp nhất (bên phải)"], "a": 1}}, {"t": "Đọc đúng từ dưới lên: 101100 = 44", "html": "<p class=\"mt-calc\">101100₂ = 32 + 8 + 4 = <b>44<\/b> ✓<\/p>", "say": "<p>Luôn kiểm tra lại bằng cách cộng trọng số. Với 45 = 101101 lỗi này không lộ vì dãy bit đối xứng, nên chọn số kiểm tra không đối xứng.<\/p>"}]}, {"label": "Lỗi: Nhóm 4 bit từ bên trái", "note": "101101₂ bị đổi sai thành 0xB1.", "steps": [{"t": "Đổi 101101₂ sang hex", "html": "<p class=\"mt-calc\">Có 6 bit, không chia hết thành nhóm 4<\/p>", "say": "<p>Nhóm từ bên trái cho “1011 | 01”.<\/p>"}, {"t": "Nhóm từ trái (sai): 1011 | 01 → B1?", "html": "<p class=\"mt-calc\">0xB1 = 177 ≠ 45 ✗<\/p>", "ask": {"q": "Khi số bit không chia hết cho 4, phải nhóm bắt đầu từ phía nào?", "o": ["Từ bên trái", "Từ bên phải (bit thấp)", "Tùy ý"], "a": 1}}, {"t": "Sửa: nhóm từ phải, thêm 0 bên trái: 0010 | 1101 → 2D", "html": "<p class=\"mt-calc\">0010 = 2 · 1101 = D → <b>0x2D<\/b> = 2 × 16 + 13 = 45 ✓<\/p>", "say": "<p>Thêm số 0 vào bên trái không làm đổi giá trị; thêm vào bên phải thì có (nhân với 2).<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l16"),"l16",[{"kind": "num", "t": "Đổi sang hệ 10", "d": "<p>Ghi kết quả ở hệ 10.<\/p>", "items": [{"q": "101101₂", "a": 45}, {"q": "11111111₂", "a": 255}, {"q": "0x7EA", "a": 2026}, {"q": "0x100", "a": 256}, {"q": "0xC8", "a": 200}], "hints": ["Trọng số hệ 2: 1, 2, 4, 8, 16, 32, 64, 128 từ phải sang trái.", "Trọng số hệ 16: 1, 16, 256, 4 096.", "C = 12, E = 14, A = 10."], "why": "45; 255 (= 2⁸ − 1); 7 × 256 + 14 × 16 + 10 = 2 026; 1 × 256 = 256; 12 × 16 + 8 = 200."}, {"kind": "num", "t": "Đổi từ hệ 10 sang hệ 2", "d": "<p>Ghi dãy bit (chỉ gồm chữ số 0 và 1, không có số 0 thừa bên trái).<\/p>", "items": [{"q": "13 = ?₂", "a": 1101}, {"q": "44 = ?₂", "a": 101100}, {"q": "100 = ?₂", "a": 1100100}, {"q": "255 = ?₂", "a": 11111111}], "hints": ["Chia liên tiếp cho 2, ghi số dư.", "Đọc số dư từ dưới lên (số dư cuối cùng là bit cao nhất).", "Kiểm tra: 100 = 64 + 32 + 4."], "why": "13 = 8 + 4 + 1 = 1101; 44 = 32 + 8 + 4 = 101100; 100 = 64 + 32 + 4 = 1100100; 255 = tám bit 1."}, {"kind": "num", "t": "Nhóm bit và số chữ số", "d": "<p>Trả lời bằng số hệ 10.<\/p>", "items": [{"q": "Một số 32 bit cần bao nhiêu chữ số hex?", "a": 8}, {"q": "0x2D có bao nhiêu bit 1?", "a": 4}, {"q": "Giá trị của 0010 1101₂ (hệ 10)?", "a": 45}, {"q": "Số lớn nhất viết được bằng 3 chữ số hex (hệ 10)?", "a": 4095}], "hints": ["Mỗi chữ số hex là 4 bit.", "0x2D = 0010 1101.", "3 chữ số hex = 12 bit."], "why": "32 ÷ 4 = 8 chữ số; 0010 1101 có 4 bit 1; 32 + 8 + 4 + 1 = 45; 0xFFF = 2¹² − 1 = 4 095."}]);

makeQuiz("quiz16","score16",[{"q": "0x1F bằng bao nhiêu trong hệ 10?", "o": ["31", "115", "16", "25"], "a": 0, "e": "1 × 16 + 15 = 31. Đáp án 115 là ghép “1” với “15” như ghép chữ; 16 là bỏ quên chữ số F (= 15)."}, {"q": "Khi đổi 10 sang hệ 2 bằng chia liên tiếp, số dư đầu tiên là gì?", "o": ["Bit cao nhất", "Số bit của kết quả", "Bit thấp nhất (bên phải)", "Luôn bằng 1"], "a": 2, "e": "Chia cho 2 lần đầu cho biết số chẵn hay lẻ: đó là bit hàng 2⁰."}, {"q": "1110 0110₂ viết ở hệ 16 là gì?", "o": ["6E", "E6", "146", "D6"], "a": 1, "e": "1110 = E, 0110 = 6 → 0xE6. Đáp án 6E là đảo thứ tự hai nhóm."}, {"q": "Đổi 1011101₂ sang hex, nhóm thế nào là đúng?", "o": ["1011 | 101 → B5", "101 | 1101 → 5D", "1011 | 1010 → BA", "0101 | 1101 → 5D"], "a": 3, "e": "Nhóm từ bên phải: 1101 = D, phần còn lại 101 thêm 0 thành 0101 = 5 → 0x5D (= 93)."}, {"q": "Vì sao kỹ sư hay viết địa chỉ bộ nhớ bằng hệ 16?", "o": ["Vì máy tính lưu hệ 16", "Vì mỗi chữ số hex ứng đúng 4 bit, gọn hơn nhị phân mà đổi lại dễ", "Vì hệ 16 có ít chữ số hơn", "Vì hệ 10 không biểu diễn được địa chỉ"], "a": 1, "e": "Máy lưu bit; hex chỉ là cách viết gọn, đổi sang bit chỉ cần thay mỗi chữ số bằng 4 bit."}]);

